import{_ as e,o as a,c as s,a3 as i}from"./chunks/framework.BwzYn71E.js";const b=JSON.parse('{"title":"种植区浮空设备教程","description":"","frontmatter":{"translationSource":{"title":"种植区浮空设备教程","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Vr9I6TOU6zz1MfmH7lI3YN","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/tutorial-floating-devices-in-farming-areas"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/tutorial-floating-devices-in-farming-areas"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/tutorial-floating-devices-in-farming-areas"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/tutorial-floating-devices-in-farming-areas"}]]},"headers":[],"relativePath":"zh/tutorial-floating-devices-in-farming-areas.md","filePath":"zh/page-Vr9I6TOU6zz1MfmH7lI3YN.md"}'),d={name:"zh/tutorial-floating-devices-in-farming-areas.md"};function r(c,t,o,l,n,h){return a(),s("div",null,[...t[0]||(t[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="种植区浮空设备教程" aria-hidden="true"></span><h1 id="种植区浮空设备教程" tabindex="-1">种植区浮空设备教程 <a class="header-anchor" href="#种植区浮空设备教程" aria-label="Permalink to &quot;种植区浮空设备教程&quot;">​</a></h1><blockquote><p>源页面 ID：<code>Vr9I6TOU6zz1MfmH7lI3YN</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Vr9I6TOU6zz1MfmH7lI3YN" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>贡献者：卖兔子的小智乃</p><p>最后更新时间：2026/10/20</p><p>视频链接：<a href="https://www.bilibili.com/video/BV1FkJB6oEuq/?share_source=copy_web&amp;vd_source=3f694229593884198d970b1b1211f6cd" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1FkJB6oEuq</a></p><p><span id="source-block-QNLhap628GkZ1M5rF6L4oJ"></span></p><span class="logistics-source-anchor" id="前言" aria-hidden="true"></span><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>目前，本教程的设备浮空只能在武陵城和祀的画的种植区实现，且由于设备的浮空高度限制，只能用于田块和设备的重叠，并不能实现设备和设备的重叠。</p><p><strong>因为高度判定问题，浮空的洒水机无法检测到田块，因此无法实现洒水机的浮空。</strong></p><p><span id="source-block-PVoqXuxCYX2DQnYmoq0LR7"></span></p><span class="logistics-source-anchor" id="作用" aria-hidden="true"></span><h2 id="作用" tabindex="-1">作用 <a class="header-anchor" href="#作用" aria-label="Permalink to &quot;作用&quot;">​</a></h2><p>通过让设备浮空，使得优质化的田块能得到更高的相邻作物加成，最佳田块布局见<a href="/endfield-skydoc/zh/planting-and-automatic-harvester-mechanics-research-and-applications">种植与自动收割机机制研究与应用</a>。</p><p><span id="source-block-dfTMIfq1lb9l2cOd38SyHr"></span></p><span class="logistics-source-anchor" id="实现方法" aria-hidden="true"></span><h2 id="实现方法" tabindex="-1">实现方法 <a class="header-anchor" href="#实现方法" aria-label="Permalink to &quot;实现方法&quot;">​</a></h2><p><strong>具有管道出入口</strong>的设备和管道件（管道分流器、管道汇流器、管道桥）都可以实现浮空，实现设备浮空有两种方法。<strong>实现设备浮空之前可以提前放好田块，并不会影响设备浮空，且能更直观地发现设备是否成功浮空。</strong></p><p><span id="source-block-QR1sFqVLeEWRkpvF8lDUAB"></span></p><span class="logistics-source-anchor" id="方法一-视频中的方法" aria-hidden="true"></span><h3 id="方法一-视频中的方法" tabindex="-1">方法一（视频中的方法） <a class="header-anchor" href="#方法一-视频中的方法" aria-label="Permalink to &quot;方法一（视频中的方法）&quot;">​</a></h3><p>第一种方法即视频中的方法，步骤如下：</p><p>步骤一：确定设备预定位置，在附近的高处放置一个管道件，从该管道件开始拉管道</p><p>步骤二：将管道拉到超过预定设备管道口三格的位置，放置管道（电脑端可按R更改管道优先方向）</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-dbcf2d17c6225813.q90-d16d4e8c7e0bbef5.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-f75c5029c5d2f504.q90-0626a48d36e941cc.webp" alt="图片"></td></tr></tbody></table><p>步骤三：删掉末端的三格管道</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-d5547f1723d6be2c.q90-a53e13326ddd8c6f.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-120ae78e8f1409f2.q90-6a3cb41558e961c1.webp" alt="图片"></td></tr></tbody></table><p>步骤四：设备的管道口对准管道后放置设备（如果设备只有管道出口则先逆转管道流向）</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-d4774003c23f05f2.q90-89eb710db9befdc3.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-e058f4e580b5c509.q90-b892675fc535f100.webp" alt="图片"></td></tr></tbody></table><p><span id="source-block-KcO4BV4zbF18YByBzjF9zW"></span></p><span class="logistics-source-anchor" id="方法二-最稳-需要先用一次方法一" aria-hidden="true"></span><h3 id="方法二-最稳-需要先用一次方法一" tabindex="-1">方法二（最稳，需要先用一次方法一） <a class="header-anchor" href="#方法二-最稳-需要先用一次方法一" aria-label="Permalink to &quot;方法二（最稳，需要先用一次方法一）&quot;">​</a></h3><p>经测试，设备可以通过跟已浮空的设备和管道件连接来实现浮空，因此得到了第二种方法。第二种方法最稳，可以让一些用第一种方法没那么容易实现浮空的地方稳定地实现浮空，但需要先通过第一种方法得到一个浮空的设备或管道件。**使用第二种方法前最好先放好田块，避免管道件直接放在了地上。**步骤如下：</p><p>步骤一：确定设备预定位置，从已浮空的设备或管道件的管道出口拉管道到预定位置（如果只有管道入口，就先贴着管道入口放一个管道分流器，再从管道分流器的出口拉管道）</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-1e19d67b251595cd.q90-f236dc91c4c4778d.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-66fc887e8e7c1026.q90-db760729c847bfcb.webp" alt="图片"></td></tr></tbody></table><p>步骤二：沿着管道放置管道件</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-4e31536ef53132ae.q90-dfc3549b6b5118a7.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-f80a139ab4a09486.q90-5a888dd63fd75ae0.webp" alt="图片"></td></tr></tbody></table><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-acf36ff3e6860cb7.q90-c445e96d58dbe776.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-73d8a9df1d294e88.q90-11393641e1d5b1d9.webp" alt="图片"></td></tr></tbody></table><p>步骤三：设备的管道口对准管道件后放置设备</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-f4df7cd3fd4e3beb.q90-27f37adbe2097f2f.webp" alt="图片"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-9a679f3060b7cb2b.q90-78f0e5e0099c2636.webp" alt="图片"></td></tr></tbody></table></div>',1)])])}const f=e(d,[["render",r]]);export{b as __pageData,f as default};
